subprocessRunHandle.evidenceQuote:
export function subprocessRunHandle(parts) {
    let disposal;
    return {
        id: parts.id,
        localAgent: undefined,
        result: parts.result,
        dispose() {
            if (disposal !== undefined)
                return disposal;
            parts.signal.removeEventListener('abort', parts.onAbort);
            parts.requestCancel();
            disposal = parts.teardown();
            return disposal;
        },
    };
}

